module sv_fix_enum_transition(
    input  logic clk,
    input  logic rst_n,
    input  logic start,
    output logic busy,
    output logic done
);
    typedef enum logic [1:0] {S_IDLE, S_RUN, S_DONE} state_t;

    state_t state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= S_IDLE;
        else begin
            case (state)
                S_IDLE:  if (start) state <= S_DONE;
                S_RUN:   state <= S_DONE;
                default: state <= S_IDLE;
            endcase
        end
    end

    always_comb begin
        busy = (state == S_RUN);
        done = (state == S_DONE);
    end
endmodule

