module sv_fix_case_arm(
    input  logic clk,
    input  logic rst_n,
    input  logic adv,
    output logic y
);
    typedef enum logic [1:0] {S_A, S_B, S_C} state_t;

    state_t state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= S_A;
        else if (adv) begin
            case (state)
                S_A:     state <= S_B;
                S_B:     state <= S_C;
                S_C:     state <= S_A;
                default: state <= S_A;
            endcase
        end
    end

    always_comb begin
        case (state)
            S_A: y = 1'b1;
            S_B: y = 1'b0;
        endcase
    end
endmodule

